#!/bin/bash
G="$(cd "$(dirname "${BASH_SOURCE[0]}")" && (pwd -W 2>/dev/null || pwd))"
NEW="$G/../../assets_new"
ask() { local out="$NEW/$1" p="$2"; shift 2; [ -f "$out" ] && { echo "skip"; return 0; }; printf '%s\n' "$p" > "$G/_prompt.txt"; node "$G/gpt.mjs" "$out" "$G/_prompt.txt" "$@" || { echo "STOP"; rm -f "$G/_prompt.txt"; exit 0; }; rm -f "$G/_prompt.txt"; echo "done"; }
ask mob_blood_bat_gpt.png "The attached image is a giant blood bat enemy from my 2D wuxia game (dark red torn leathery wings, black furry body, glowing red eyes, white fangs). Draw a NEW sprite sheet of the SAME bat with 8 frames, in a hand-drawn cel-shaded style with clear black outlines, more detailed. Layout: 4 columns x 2 rows, each frame the same size, the whole bat fully visible in every cell (wings not cropped), flat solid magenta background (#FF00FF), no text, no borders, no grid lines, no shadows, facing RIGHT, side view, the BODY kept at the same height and position in every cell.
Top row = FLYING cycle: 1 wings fully up, 2 wings half down, 3 wings fully down, 4 wings half up.
Bottom row = ATTACK: 1 wings pulled back about to dive, 2 diving forward with fangs bared, 3 biting forward with a small red slash arc and blood mist, 4 flapping back up." "$NEW/mob_blood_bat_walk.png"
ask mob_ice_mage_walk_gpt.png "The attached image is a frost sorceress enemy from my 2D wuxia game (white and pale-blue silk robes, white veil, snowflake hair ornaments, short silver staff with an ice crystal). Draw a NEW walk-cycle sprite sheet of the SAME woman in the same hand-drawn cel-shaded style with black outlines, 3/4 side view facing RIGHT. Frame 1: right leg forward stride. Frame 2: legs passing (feet together). Frame 3: left leg forward stride. Frame 4: legs passing. The legs and robe hem must clearly change between frames. Layout: 2x2 grid, 4 frames, same size, full body visible, feet on the same ground line, flat solid magenta background (#FF00FF), no text, no borders, no grid lines, no shadows." "$NEW/mob_ice_mage_walk.png"
echo ALLDONE
